-- Exact manufacturer pilot, two products only. No price/stock/photo/access changes.
begin;
set local lock_timeout='5s';set local statement_timeout='30s';set local standard_conforming_strings=on;
create temporary table manufacturer_plan(payload jsonb) on commit drop;
insert into manufacturer_plan values('[{"id":247,"sku":"V11HB60042","brand":"Epson","name":"Проєктор Epson EB-994F FHD (V11HB60042)","source":"https://www.epson-africa.com/projectors/professional/business-education/eb-994f-v11hb60042","before":{"specifications":{"Вхід":": HDMI x2, WiFi","Вихід":": stereo mini jack, USB Type A, USB Type B","Шум (дБ)":": 37/28","Маса (кг)":": 3.1","Контраст":": 16000:1","Технологія":": 3LCD","Яскравість":"4100 лм","Динамік (Вт)":": 16","Призначення":"Універсальний","Фокусування":": ручне","Габарити (мм)":": 309‎ x 283 x 105","Джерело світла":"Лампа","Світловий потік (лм)":": 4100","Роздільна здатність":"1920 x 1080","Технологія проекції":"3LCD","Енергоспоживання (Вт)":": 327","Проекційне співвідношення":"1.3-2.09","Оптичний трансфокатор (зум)":": x1.6","Джерело світла (тип, термін роботи)":": UHP 230W, 5500/12000","Корекція трапецеїдальних спотворень":": V= ±30° H= ±30°"},"description":"<!--technoroom-rich-text:v1--><p>Epson EB-994F (V11HB60042) — білий проєктор для презентацій із технологією 3LCD та рідною роздільною здатністю Full HD 1920 × 1080. Кольоровий світловий потік становить 4100 лм, контрастність — 16 000:1.</p><p>Лампове джерело світла має ресурс до 6500 годин у звичайному режимі та до 17 000 годин в економічному. Фокусування — ручне. Фокусна відстань об’єктива — 18,2–29,1 мм, діафрагма — F/1,51–1,77.</p><p>Кольорові режими: «Класна дошка», «Кіно», «Динамічний», «Презентація» та sRGB. Послідовний інтерфейс — RS-232C, сервісний порт — USB Type-A.</p><ul><li>Діагональ проєкції: 31–304 дюйми (787,4–7721,6 мм).</li><li>Співвідношення сторін: 16:9.</li><li>Відтворення кольорів: до 1,07 млрд кольорів.</li><li>Ручне фокусування та масштабування.</li><li>Мережеві підключення: Ethernet і Wi-Fi.</li><li>Вбудований динамік потужністю 16 Вт.</li></ul>","manual_overrides":{}},"after":{"specifications":{"Вхід":": HDMI x2, WiFi","Вихід":": stereo mini jack, USB Type A, USB Type B","Шум (дБ)":": 37/28","Маса (кг)":": 3.1","Контраст":": 16000:1","Технологія":": 3LCD","Яскравість":"4100 лм","Динамік (Вт)":": 16","Призначення":"Універсальний","Фокусування":": ручне","Габарити (мм)":"309 × 293 × 105 (Ш × Г × В)","Джерело світла":"Лампа","Світловий потік (лм)":": 4100","Роздільна здатність":"1920 x 1080","Технологія проекції":"3LCD","Енергоспоживання (Вт)":"284 (звичайний режим)","Проекційне співвідношення":"1.3-2.09","Оптичний трансфокатор (зум)":": x1.6","Корекція трапецеїдальних спотворень":": V= ±30° H= ±30°","Ресурс джерела світла (звичайний режим)":"6500 год","Ресурс джерела світла (екорежим)":"17000 год","Енергоспоживання (екорежим)":"181 Вт","Енергоспоживання (режим очікування)":"0,3 Вт"},"description":"<!--technoroom-rich-text:v1--><p>Epson EB-994F (V11HB60042) — білий проєктор для презентацій із технологією 3LCD та рідною роздільною здатністю Full HD 1920 × 1080. Кольоровий світловий потік становить 4100 лм, контрастність — 16 000:1.</p><p>Лампове джерело світла має ресурс до 6500 годин у звичайному режимі та до 17 000 годин в економічному. Фокусування — ручне. Фокусна відстань об’єктива — 18,2–29,1 мм, діафрагма — F/1,51–1,77.</p><p>Кольорові режими: «Класна дошка», «Кіно», «Динамічний», «Презентація» та sRGB. Послідовний інтерфейс — RS-232C, сервісний порт — USB Type-A.</p><ul><li>Діагональ проєкції: 31–304 дюйми (787,4–7721,6 мм).</li><li>Співвідношення сторін: 16:9.</li><li>Відтворення кольорів: до 1,07 млрд кольорів.</li><li>Ручне фокусування та масштабування.</li><li>Мережеві підключення: Ethernet і Wi-Fi.</li><li>Вбудований динамік потужністю 16 Вт.</li></ul>"},"changes":["Габарити (мм)","Енергоспоживання (Вт)","Джерело світла (тип, термін роботи)","Ресурс джерела світла (звичайний режим)","Ресурс джерела світла (екорежим)","Енергоспоживання (екорежим)","Енергоспоживання (режим очікування)"]},{"id":4331,"sku":"6928C001","brand":"Canon","name":"БФП А4 кол. Canon i-SENSYS MF667Cdw з Wi-Fi (6928C001)","source":"https://canon.a.bigcontent.io/v1/static/i-sensys-mf664cdw_i-sensys-mf667cdw_data