00 л.","Формат":"A4","Тип друку":"Кольоровий","Мови опису":"UFRII, PCL 5c, PCL6, Adobe PostScript 3","Інтерфейси":"USB 2.0 Hi-Speed; Ethernet 10/100/1000Base-T; Wi-Fi 802.11b/g/n; пряме бездротове підключення","Тип пристрою":"БФП","Навантаження":"н/д","Дуплексний друк":"Є","Швидкість друку":"до 25 стор/хв ч/б/колір (A4)","Швидкість факсу":"33,6 кбіт/с","Панель керування":"кольоровий сенсорний РК-дисплей 12.7 см","Технологія друку":"Лазерний","Щільність паперу":"60–163 г/м²; до 200 г/м² для крейдованого паперу","Витратні матеріали":"6365C002 Картридж 075 (чорний, 1400 сторінок) 6364C002 Картридж 075 (блакитний, 1300 сторінок) 6362C002 Картридж 075 (жовтий, 1300 сторінок) 6363C002 Картридж 075 (пурпуровий, 1300 сторінок) 6369C002 Картридж 075H (чорний, 3500 сторінок) 6368C002 Картридж 075H (блакитний, 2500 сторінок) 6367C002 Картридж 075H (пурпуровий, 2500 сторінок) 6366C002 Картридж 075H (жовтий, 2500 сторінок) В комплект поставки входять стартові картриджі 075 (чорним (700 сторінок) і C/M/Y (500 сторінок).","Швидкість копіювання":"до 25 копій/хв (A4), до 15 з/хв - двосторон.","макс. кількість копій":"999","Типи друкованих носіїв":"папір (Звичайний, відновлений, цупкий, тонкий, кольоровий і глянсовий папір, етикетки, листівки, конверти)","Цифрова передача даних":"scan to e-mail (TIFF, JPEG, PDF, scan to PC TIFF / JPEG / PDF / компактний PDF / PDF із можливістю пошуку / шифрований PDF4 / PDF із цифровим підписом4 / PDF/A-1b","Документ постачальника":"https://canon.a.bigcontent.io/v1/static/i-sensys-mf664cdw_i-sensys-mf667cdw_datasheet_uk_final_hr_b009b90bce574bdbb3acd807cc13aea1","Додаткові функції друку":"Захищений друк; друк з USB; AirPrint; Canon PRINT; Mopria; Microsoft Universal Print; друк штрих-кодів з додатковим комплектом E1E","Масштабування копіювання":"25-400%","Роздільна здатність друку":"1200 × 1200 dpi","Роздільна здатність копіювання":"600 × 600 dpi","Оптична роздільна здатність сканування":"600 × 600 dpi","Покращена роздільна здатність сканування":"9600 × 9600 dpi","Пам’ять факсу":"До 512 сторінок","Оперативна пам’ять":"1 ГБ","Максимальна кількість адресатів факсу":"299","Місткість ADF":"50 аркушів","Щільність паперу ADF":"50–105 г/м²","Глибина кольору сканування":"24 біти (вхід / вихід)","Швидкість двостороннього друку":"До 15 зобр/хв (A4)","Час виходу першої сторінки":"Ч/б: до 10,90 с; колір: до 10,93 с"},"description":"<!--technoroom-rich-text:v1--><p>Canon i-SENSYS MF667Cdw (6928C001) — кольоровий лазерний БФП формату A4 для друку, копіювання, сканування та роботи з факсом.</p><p>Пристрій підтримує автоматичний двосторонній друк і має однопрохідний двосторонній автоподавач документів. Для підключення доступні USB, Ethernet та Wi-Fi. Керування здійснюється через кольоровий сенсорний дисплей.</p><p>Параметри друку, копіювання й сканування наведено окремо в таблиці характеристик.</p>"},"changes":["ADF","дозвіл","пам''ять","Інтерфейс","Мови опису","Інтерфейси","Швидкість факсу","Щільність паперу","Сканер (швидкість","Витратні матеріали","макс. кількість копій","Додаткові функції друку","Mopria, Canon PRINT Business -SENSYS MF667Cdw","багатоадресне розсилання","пристрій автоматичної подачі документів (ADF)","до 15 зображень/хв. двосторонній друк до 15 зобр./хв., (A4), дозвіл","10Base-T/100BASE-TX/1000Base-T, бездротовий 802.11b/g/n, бездротове пряме підключення Панель керування","Роздільна здатність друку","Роздільна здатність копіювання","Оптична роздільна здатність сканування","Покращена роздільна здатність сканування","Пам’ять факсу","Оперативна пам’ять","Максимальна кількість адресатів факсу","Місткість ADF","Щільність паперу ADF","Глибина кольору сканування","Швидкість двостороннього друку","Час виходу першої сторінки"]}]'::jsonb);
do $pilot$
declare item jsonb; original_row jsonb; after_row jsonb; saved jsonb; changed_key text;
begin
 if not (select relrowsecurity from pg_class where oid='technoroom_maintenance.product_repair_backup'::regclass) then raise exception 'Protected backup table required';end if;
 if (select jsonb_array_length(payload) from manufacturer_plan)<>2 then raise exception 'Unexpected pilot size';end if;
 perform id from products where id in (247,4331) order by id for update;
 for item in select value from manufacturer_plan,jsonb_array_elements(payload) loop
  if not ((item->>'id'='247' and item->>'sku'='V11HB60042' and item->>'brand'='Epson') or (item->>'id'='4331' and item->>'sku'='6928C001' and item->>'brand'='Canon')) then raise exception 'Unexpected identity';end if;
  select to_jsonb(p) into original_row from products p where id=(item->>'id')::bigint;
  if original_row is null or original_row->>'sku' is distinct from item->>'sku' or original_row->>'brand' is distinct from item->>'brand' or original_row->>'name' is distinct from item->>'name' then raise exception 'Identity changed';end if;
  select before_row into saved from technoroom_maintenance.product_repair_backup where operation='manufacturer-pilot-20261027' and product_id=(item->>'id')::bigint;
  if saved is null then raise exception 'Backup missing';end if;
  if original_row->'specifications' is distinct from item->'after'->'specifications' or original_row->'description' is distinct from item->'after'->'description' or coalesce(original_row->'manual_overrides','{}'::jsonb) is distinct from item->'before'->'manual_overrides' then raise exception 'Card changed after repair';end if;
  perform set_config('technoroom.import_write','true',true);
  update products set specifications=saved->'specifications',description=saved->>'description' where id=(item->>'id')::bigint;
  select to_jsonb(p) into after_row from products p where id=(item->>'id')::bigint;
  if after_row->'specifications' is distinct from saved->'specifications' or after_row->'description' is distinct from saved->'description' or (after_row-array['specifications','description','updated_at']) is distinct from (original_row-array['specifications','description','updated_at']) then raise exception 'Unexpected product side effect';end if;
 end loop;
end $pilot$;
commit;
